import UserProfileCard from "./UserProfileCard";
import Toast from "./Toast";

export default function NgoDashboard({ token, msg, setMsg, events, setEvents, ngoPanel }) {
  const [me, setMe] = useState(null);
  const [newEvent, setNewEvent] = useState({
    title: "",
    description: "",
    location: "",
    date: "",
    requiredVolunteers: 0
  });
  const [volunteers, setVolunteers] = useState(null);
  const [donations, setDonations] = useState(null);
  const [myDonations, setMyDonations] = useState(null);
  const [totalRaised, setTotalRaised] = useState(0);
  const [achievements, setAchievements] = useState(null);
  const [selectedParticipants, setSelectedParticipants] = useState(null);
  const [toast, setToast] = useState({ message: '', type: 'success' });
  const [feedback, setFeedback] = useState("");
  const [feedbackMsg, setFeedbackMsg] = useState("");

  /* ----------------------------------------
      FETCH LOGGED-IN USER /me (PROFILE)
  ---------------------------------------- */
  useEffect(() => {
    if (!token) return;

    fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/auth/me", {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(d => setMe(d))
      .catch(() => {});
  }, [token]);

  function createEvent(e) {
    e.preventDefault();

    fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/create-event", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify(newEvent)
    })
      .then(r => r.json())
      .then(d => {
        setMsg(d.msg);
        if (d.event) setEvents([...events, d.event]);
      });
  }

  useEffect(() => {
    if (!token) return;
    (async () => {
      try {
        const res = await fetch(
          (process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/achievements",
          { headers: { Authorization: `Bearer ${token}` } }
        );
        const d = await res.json();
        setAchievements(d);
      } catch (e) {}
    })();
  }, [token]);

  // FUNCTION to get most recent event date
  function getRecentEventDate() {
    if (!events || !events.length) return "No events yet";

    const sorted = [...events].sort((a, b) => {
      const da = new Date(a.date || a.createdAt || "");
      const db = new Date(b.date || b.createdAt || "");
      return db - da;
    });

    const ev = sorted[0];
    const raw = ev.date || ev.createdAt;

    const parsed = new Date(raw);
    if (isNaN(parsed.getTime())) return "No valid date";

    return parsed.toLocaleDateString();
  }

  // ----------------------------------------
  // CORRECTED FUNCTION: Uses actual fetch call
  // ----------------------------------------
  async function submitFeedback(e) {
    e.preventDefault();
    if (!token) {
        setFeedbackMsg("Please login to submit feedback.");
        return;
    }
    if (feedback.trim() === "") {
        setFeedbackMsg("Please write some feedback before submitting.");
        return;
    }
    
    setFeedbackMsg("Submitting feedback...");

    try {
      // NOTE: Targeting /api/actions/feedback based on your backend structure
      const res = await fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/actions/feedback", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}` // Authentication is required
        },
        body: JSON.stringify({ text: feedback }) // Send the text
      });

      const data = await res.json();
      
      if (res.ok) {
        setFeedbackMsg(data.message); // Should say "Feedback recorded successfully"
        setFeedback(""); // Clear the input on success
      } else {
        // Handle server-side errors (e.g., 400 Bad Request, 401 Unauthorized)
        setFeedbackMsg(`Error: ${data.message || 'Failed to submit feedback.'}`);
      }
    } catch (error) {
      console.error("Feedback submission error:", error);
      setFeedbackMsg("An unexpected network error occurred.");
    }
  }
  // ----------------------------------------


  return (
    <div className="panel" style={{ display: 'flex', gap: 16 }}>

      {/* LEFT PANEL */}
      <div style={{ width: 320, flexShrink: 0 }}>

        {/* FIXED PROFILE CARD — Now shows correct Name, Email, Role, Image */}
        <UserProfileCard me={me} activities={me?.activities || []} />

        {/* QUICK LINKS UNDER PROFILE */}
        <div
          style={{
            marginTop: 16,
            background: "#f8fbff",
            padding: 16,
            borderRadius: 12,
            border: "2px solid #2196F3",
            boxShadow: "0 2px 12px rgba(0,0,0,0.05)"
          }}
        >
          <h4 style={{ marginBottom: 12, color: "#0b65c2" }}>Event Info</h4>

          <p><strong>Total Events:</strong> {events?.length || 0}</p>

          <p>
            <strong>Last Event Date:</strong> {getRecentEventDate()}
          </p>
        </div>

        {/* FEEDBACK SECTION */}
        <div
          style={{
            marginTop: 16,
            background: "#fffde7", // Light yellow background for feedback
            padding: 16,
            borderRadius: 12,
            border: "2px solid #ffc107", // Amber border
            boxShadow: "0 2px 12px rgba(0,0,0,0.05)"
          }}
        >
          <h4 style={{ marginBottom: 12, color: "#ff8f00" }}>Give Feedback</h4>
          <form onSubmit={submitFeedback}>
            <textarea
              placeholder="Tell us what you think..."
              value={feedback}
              onChange={e => setFeedback(e.target.value)}
              rows="4"
              style={{ width: '100%', padding: 8, marginBottom: 8, borderRadius: 4, border: '1px solid #ccc' }}
            ></textarea>
            <button type="submit" style={{ width: '100%', backgroundColor: '#ff9800', color: 'white' }}>Submit</button>
          </form>
          {feedbackMsg && <p style={{ marginTop: 8, fontSize: 14, color: feedbackMsg.includes('Error') ? '#f44336' : '#4CAF50' }}>{feedbackMsg}</p>}
        </div>
      </div>

      {/* MIDDLE PANEL: Main Content (Create Event, Data Views) */}
      <div style={{ flex: 1 }}>

        <h4>Create New Event</h4>

        <form onSubmit={createEvent}>
          <input
            type="text"
            placeholder="Event Title"
            value={newEvent.title}
            onChange={e => setNewEvent({ ...newEvent, title: e.target.value })}
            required
          />

          <textarea
            placeholder="Event Description"
            value={newEvent.description}
            onChange={e => setNewEvent({ ...newEvent, description: e.target.value })}
          ></textarea>

          <input
            type="text"
            placeholder="Location"
            value={newEvent.location}
            onChange={e => setNewEvent({ ...newEvent, location: e.target.value })}
          />

          <input
            type="date"
            value={newEvent.date}
            onChange={e => setNewEvent({ ...newEvent, date: e.target.value })}
          />

          <input
            type="number"
            placeholder="Required Volunteers"
            value={newEvent.requiredVolunteers}
            onChange={e => setNewEvent({ ...newEvent, requiredVolunteers: e.target.value })}
          />

          <button type="submit">Create Event</button>
        </form>

        <p className="msg">{msg}</p>

        {/* BUTTON BLOCK */}
        <div style={{ marginTop: 18 }}>
          <button
            onClick={async () => {
              if (!token) return setMsg("Login first");
              const res = await fetch(
                (process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/volunteers",
                { headers: { Authorization: `Bearer ${token}` } }
              );
              const d = await res.json();
              setVolunteers(d.volunteers || []);
              setDonations(null);
              setAchievements(null);
              setSelectedParticipants(null);
            }}
          >
            View Volunteers
          </button>

          <button
            style={{ marginLeft: 8 }}
            onClick={async () => {
              if (!token) return setMsg("Login first");
              const res = await fetch(
                (process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/donations",
                { headers: { Authorization: `Bearer ${token}` } }
              );
              const d = await res.json();
              setDonations(d.donations || []);
              setVolunteers(null);
              setAchievements(null);
              setSelectedParticipants(null);
            }}
          >
            View Donations
          </button>

          <button
            style={{ marginLeft: 8 }}
            onClick={async () => {
              if (!token) return setMsg("Login first");
              const res = await fetch(
                (process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/achievements",
                { headers: { Authorization: `Bearer ${token}` } }
              );
              const d = await res.json();
              setAchievements(d);
              setVolunteers(null);
              setDonations(null);
              setSelectedParticipants(null);
            }}
          >
            View Achievements
          </button>

          <button
            style={{ marginLeft: 8 }}
            onClick={async () => {
              if (!token) return setMsg("Login first");
              const res = await fetch(
                (process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/volunteers",
                { headers: { Authorization: `Bearer ${token}` } }
              );
              const d = await res.json();
              setSelectedParticipants(d.volunteers || []);
              setVolunteers(null);
              setDonations(null);
              setAchievements(null);
            }}
          >
            View Participants
          </button>
        </div>

        {volunteers && (
          <div style={{ marginTop: 12 }}>
            <h4>Volunteers</h4>
            {volunteers.length ? (
              volunteers.map(v => (
                <div key={v.id} style={{ padding: 8, borderBottom: "1px solid #eee" }}>
                  <strong>{v.user_name}</strong> ({v.user_email}) — {v.event_title}
                </div>
              ))
            ) : (
              <p>No volunteers yet.</p>
            )}
          </div>
        )}

        {donations && (
          <div style={{ marginTop: 12 }}>
            <h4>Donations</h4>
            {donations.length ? (
              donations.map(dn => (
                <div key={dn.id} style={{ padding: 8, borderBottom: "1px solid #eee" }}>
                  <strong>{dn.donor_name}</strong> ({dn.donor_email}) — ₹{dn.amount}
                </div>
              ))
            ) : (
              <p>No donations yet.</p>
            )}
          </div>
        )}

        {selectedParticipants && (
          <div style={{ marginTop: 12 }}>
            <h4>Participants</h4>
            {selectedParticipants.length ? (
              selectedParticipants.map(p => (
                <div key={p.id} style={{ padding: 8, borderBottom: "1px solid #eee" }}>
                  <strong>{p.user_name}</strong> — {p.user_email} (Event: {p.event_title})
                </div>
              ))
            ) : (
              <p>No participants yet.</p>
            )}
          </div>
        )}

        {achievements && (
          <div style={{ marginTop: 12 }}>
            <h4>Achievements</h4>
            <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
              <div className="stat-card">
                <div className="stat-num">{achievements.totals.totalEvents}</div>
                <div className="stat-label">Total Events</div>
              </div>
              <div className="stat-card">
                <div className="stat-num">{achievements.totals.totalVolunteers}</div>
                <div className="stat-label">Volunteers</div>
              </div>
              <div className="stat-card">
                <div className="stat-num">₹{achievements.totals.totalDonations}</div>
                <div className="stat-label">Donations</div>
              </div>
              <div className="stat-card">
                <div className="stat-num">{achievements.successfulEvents}</div>
                <div className="stat-label">Successful Events</div>
              </div>
            </div>

            <div style={{ marginTop: 12 }}>
              <h5>Top Events</h5>
              {achievements.topEvents && achievements.topEvents.length ? (
                achievements.topEvents.map(ev => (
                  <div
                    key={ev.id}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 12,
                      padding: 8,
                      borderBottom: "1px solid #eee"
                    }}
                  >
                    <img
                      src={ev.image_url || "https://via.placeholder.com/100x60"}
                      alt="ev"
                      style={{ width: 100, height: 60, objectFit: "cover", borderRadius: 6 }}
                    />
                    <div>
                      <div style={{ fontWeight: 600 }}>{ev.title}</div>
                      <div style={{ fontSize: 13, color: "#666" }}>
                        Volunteers: {ev.volunteers_count}
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <p>No top events yet.</p>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
